import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Complete actual Tool, Miraidon and Mega Latias profiles; controlled 60-card fixtures, no relaxed card programs. */
public final class GeneratedRuleBatch70Test {
    static final UUID A=DamageCounterSuccessTest.A,B=DamageCounterSuccessTest.B;
    static final String MIRAIDON="me5_en_028",LATIAS="me1_en_100";
    static final CardDatabase DB=BundledRules.loadCardDefinitions();static final CombatCatalog COMBAT=BundledCombatData.load();
    static void check(boolean b,String s){DamageCounterSuccessTest.check(b,s);}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DamageCounterSuccessTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return DamageCounterSuccessTest.active(m,p);}
    public static void main(String[] args){for(String id:List.of("me5_en_082","me5_en_113")){printed(id);for(String mode:List.of("NORMAL","SIMULTANEOUS","PROTECTED","MEGA_HOST"))battle(id,mode);}System.out.println("GeneratedRuleBatch70Test passed: both complete Tremendous Bomb printings, actual Mega Latias300 damage after Energy discard, actual Miraidon lethal reaction,3-Prize simultaneous KO, Trainer prevention and excluded Mega host");}
    static void printed(String id){var d=DB.find(id).orElseThrow();var t=COMBAT.trainer(id).orElseThrow();check(d.effectSupport()==EffectSupport.SUPPORTED&&d.trainerCategory()==TrainerCategory.TOOL&&d.regulationMark().equals("J")&&d.copyLimit()==4,"Bomb metadata incorrect");check(t.automaticEffects().size()==1,"Bomb must have one persistent event source");var a=t.automaticEffects().getFirst();check(a.eventPolicy() instanceof DamageTriggerPolicy,"Bomb used wrong timing");var p=(DamageTriggerPolicy)a.eventPolicy();check(p.minimumDamage()==240&&p.attackerFamilies().equals(Set.of(PokemonFamily.MEGA_EVOLUTION_EX))&&p.activeOnly()&&p.opponentOnly()&&!p.lethalOnly()&&!p.optional(),"Bomb event filter lost printed semantics");var triggers=a.effectProgram().triggers();check(triggers.size()==1&&triggers.getFirst().conditions().size()==1,"Missing non-Mega host condition");var effects=triggers.getFirst().effects();check(effects.size()==2&&effects.getFirst().type().equals("damage_counter")&&effects.getFirst().target()==EffectTarget.ATTACKING_POKEMON&&DamageCounterEffect.from(effects.getFirst()).amount()==12&&effects.getFirst().arguments().get("bind").equals("placed"),"Actual Bomb fixed counter producer wrong");check(effects.getLast().type().equals("conditional")&&effects.getLast().conditions().getFirst().type()==ConditionType.BOUND_COUNT&&effects.getLast().effects().getFirst().type().equals("discard_source"),"Actual Bomb must discard only after successful placement");}
    static ServerMatch game(String tool,boolean megaHost){var defs=new ArrayList<CardDefinition>();for(String id:List.of(tool,MIRAIDON,LATIAS))defs.add(DB.find(id).orElseThrow());defs.add(new CardDefinition("wild","夹具彩能",CardCategory.ENERGY,TrainerCategory.NONE,"J",Set.of("international"),false,false,60,Map.of(),EffectSupport.SUPPORTED,null));var catalog=new CombatCatalog(Map.of(MIRAIDON,COMBAT.pokemon(MIRAIDON).orElseThrow(),LATIAS,COMBAT.pokemon(LATIAS).orElseThrow()),Map.of(),Map.of(tool,COMBAT.trainer(tool).orElseThrow()),Map.of("wild",new EnergyProfile(List.of(new EnergyProfile.Unit(EnumSet.allOf(EnergyType.class))))));var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();String pokemon=p.equals(A)&&!megaHost?MIRAIDON:LATIAS;for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,i<24?pokemon:i<28?tool:"wild"));decks.add(cards);}
        for(int seed=0;seed<1000;seed++){var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicPokemon()).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);m.endTurn(A);m.endTurn(B);if(m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals(tool)))continue;return m;}throw new AssertionError("No actual Bomb fixture");}
    static void battle(String id,String mode){var m=game(id,mode.equals("MEGA_HOST"));var card=hand(m,A,id);UUID attacker=active(m,B);m.playTrainer(A,card.instanceId(),active(m,A));for(int i=0;i<3;i++){var e=hand(m,B,"wild");m.attachEnergyByEffect(A,B,EffectSourceZone.HAND,e.instanceId(),B,attacker);}if(mode.equals("SIMULTANEOUS"))m.placeDamageCountersByEffect(A,B,attacker,16);m.endTurn(A);if(mode.equals("PROTECTED"))StarterDeck100CounterMoveTest.shield(m,B,attacker,"TRAINER");var rng=m.randomTranscript();m.attack(B,"illusory-impulse");check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.privateView(A).discard().contains(card)&&m.privateView(B).discard().stream().filter(c->c.definitionId().equals("wild")).count()==3,"Actual300 attack, Energy discard, host Tool cleanup or KO continuation incorrect");
        if(!mode.equals("SIMULTANEOUS"))check(m.activePokemonView(B).damage()==(mode.equals("NORMAL")?120:0),"Actual Bomb ignored prevention or host family");else check(m.privateView(B).discard().stream().anyMatch(c->c.definitionId().equals(LATIAS)),"Actual Mega attacker survived lethal12counters");check(m.randomTranscript().equals(rng),"Bomb unexpectedly used RNG");int cap=12;while(m.phase()==MatchPhase.PRIZE_SELECTION&&cap-->0)m.takePrizeAt(m.pendingChoicePlayer(),0);while(m.phase()==MatchPhase.CHOOSE_REPLACEMENT&&cap-->0){UUID p=m.pendingChoicePlayer();m.chooseReplacement(p,m.benchPokemonView(p).getFirst().pokemonId());}check(cap>0&&m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(A)&&m.privateView(A).prizes().size()==(mode.equals("SIMULTANEOUS")?3:6)&&m.privateView(B).prizes().size()==(mode.equals("MEGA_HOST")?3:5),"Actual Prize values or turn progression changed");}
}
